import { useState } from "react";
import { useCart } from "@/context/CartContext";
import { useAuth } from "@/context/AuthContext";
import { useLocation } from "@/context/LocationContext";
import { useNavigate, Link } from "react-router-dom";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Minus,
  Plus,
  Trash2,
  Ticket,
  Clock,
  Cake,
} from "lucide-react";
import CouponUnlock from "@/components/CouponUnlock";
import api from "@/lib/api";
import { toast } from "sonner";

const PLATFORM_FEE = 0;
const DELIVERY = 0;
const PACKAGING = 10;

// Replace later with your UPI ID
const UPI_ID = "v.rakesh22@ybl";
const MERCHANT_NAME = "SLV Bakery";

export default function Cart() {
  const { items, updateQty, subtotal, clearCart } = useCart();
  const { user } = useAuth();
  const { status } = useLocation();
  const nav = useNavigate();

  const [coupon, setCoupon] = useState("");
  const [discount, setDiscount] = useState(0);
  const [applied, setApplied] = useState("");
  const [payment, setPayment] = useState("COD");
  const [placing, setPlacing] = useState(false);

  const total = Math.max(
    0,
    subtotal +
    PLATFORM_FEE +
    DELIVERY +
    PACKAGING -
    discount
  );

  const inHours = (() => {
    const h = new Date().getHours();
    return h >= 11 && h < 23;
  })();

  // Generate Dynamic Order ID
  const orderId = `SLV${Date.now()}`;

  // Dynamic UPI Link
  const upiUrl = `upi://pay?pa=${UPI_ID}&pn=${encodeURIComponent(
    MERCHANT_NAME
  )}&am=${total.toFixed(
    2
  )}&cu=INR&tn=${orderId}`;

  // Dynamic QR Image
  const qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=250x250&data=${encodeURIComponent(
    upiUrl
  )}`;

  const apply = async () => {
    try {
      const { data } = await api.post("/coupons/validate", {
        code: coupon,
        subtotal,
      });

      setDiscount(data.discount);
      setApplied(data.code);

      toast.success(data.message);
    } catch (e) {
      toast.error(
        e?.response?.data?.detail || "Invalid coupon"
      );
    }
  };

  const place = async () => {
    if (!user) {
      toast.error("Please login first");
      nav("/login");
      return;
    }

    if (!inHours) {
      toast.error("Orders accepted 11 AM – 11 PM only");
      return;
    }

    if (status && !status.in_range) {
      toast.error(
        "Delivery unavailable at your location"
      );
      return;
    }

    if (!items.length) return;

    // Prevent placing order before payment verification
    if (payment === "ONLINE") {
      toast.info(
        "Please complete the UPI payment before placing your order."
      );
      return;
    }

    setPlacing(true);

    try {
      const payload = {
        items: items.map((i) => ({
          product_id: i.product_id,
          name: i.product?.name,
          price: i.product?.discount_price,
          quantity: i.quantity,
          weight: i.weight,
        })),

        subtotal,

        platform_fee: PLATFORM_FEE,
        delivery_charge: DELIVERY,
        packaging: PACKAGING,

        discount,
        total,

        coupon_code: applied || null,

        address: user.address,
        phone: user.phone,

        payment_method: payment,

        lat: status?.lat,
        lng: status?.lng,
      };

      const { data } = await api.post(
        "/orders",
        payload
      );

      toast.success(
        `Order placed! ${data.order_no}`
      );

      await clearCart();

      nav(`/orders/${data.id}`);
    } catch (e) {
      toast.error("Failed to place order");
    }

    setPlacing(false);
  };
  if (!items.length)
    return (
      <div
        className="max-w-2xl mx-auto text-center py-20 px-4"
        data-testid="empty-cart"
      >
        <div className="text-6xl mb-4">
          <Cake className="w-24 h-24 text-[#D97706] animate-bounce mx-auto" />
        </div>

        <h2 className="font-display text-2xl font-bold">
          Your cart is empty
        </h2>

        <p className="text-[#5C4A3D] mt-2">
          Add some fresh bakery goodness to get started.
        </p>

        <Link
          to="/categories"
          className="btn-primary inline-block mt-6 rounded-full px-6 py-2.5 text-sm uppercase-tracked"
        >
          Shop Now
        </Link>
      </div>
    );

  return (
    <div
      className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-8"
      data-testid="cart-page"
    >
      <h1 className="font-display text-3xl md:text-4xl font-bold mb-6">
        Your Cart
      </h1>

      <div className="grid lg:grid-cols-[1fr_400px] gap-6">

        {/* LEFT SIDE */}

        <div className="space-y-3">

          <CouponUnlock />

          {items.map((i) => (
            <div
              key={i.product_id + (i.weight || "")}
              className="bg-white border border-[#E6DFD5] rounded-2xl p-4 flex gap-4"
              data-testid={`cart-item-${i.product_id}`}
            >
              <img
                src={i.product?.images?.[0]}
                alt={i.product?.name}
                className="w-20 h-20 rounded-xl object-cover"
              />

              <div className="flex-1 min-w-0">

                <div className="font-semibold">
                  {i.product?.name}
                </div>

                <div className="text-xs text-[#5C4A3D]">
                  {i.weight}
                </div>

                <div className="mt-1 font-bold">
                  ₹
                  {(
                    (i.product?.discount_price || 0) *
                    i.quantity
                  ).toFixed(0)}
                </div>

              </div>

              <div className="flex flex-col items-end justify-between">

                <button
                  onClick={() =>
                    updateQty(i.product_id, 0)
                  }
                  data-testid={`remove-${i.product_id}`}
                >
                  <Trash2 className="w-4 h-4 text-[#BE123C]" />
                </button>

                <div className="flex items-center border border-[#E6DFD5] rounded-full">

                  <button
                    className="w-8 h-8 flex items-center justify-center"
                    onClick={() =>
                      updateQty(
                        i.product_id,
                        i.quantity - 1
                      )
                    }
                  >
                    <Minus className="w-3 h-3" />
                  </button>

                  <div className="w-8 text-center text-sm">
                    {i.quantity}
                  </div>

                  <button
                    className="w-8 h-8 flex items-center justify-center"
                    onClick={() =>
                      updateQty(
                        i.product_id,
                        i.quantity + 1
                      )
                    }
                  >
                    <Plus className="w-3 h-3" />
                  </button>

                </div>

              </div>

            </div>
          ))}

        </div>

        {/* RIGHT SIDE */}

        <div className="space-y-4 lg:sticky lg:top-24 h-fit">

          {/* ORDER SUMMARY */}

          <div
            className="bg-white border border-[#E6DFD5] rounded-2xl p-5"
            data-testid="order-summary"
          >

            <h3 className="font-display text-xl font-bold mb-4">
              Order Summary
            </h3>

            <div className="flex gap-2 mb-4">

              <div className="flex-1 relative">

                <Ticket className="w-4 h-4 text-[#5C4A3D] absolute left-3 top-1/2 -translate-y-1/2" />

                <Input
                  value={coupon}
                  onChange={(e) =>
                    setCoupon(
                      e.target.value.toUpperCase()
                    )
                  }
                  placeholder="Coupon code"
                  className="pl-9 rounded-full"
                  data-testid="coupon-input"
                />

              </div>

              <Button
                onClick={apply}
                className="btn-primary rounded-full"
                data-testid="apply-coupon"
              >
                Apply
              </Button>

            </div>

            <div className="space-y-2 text-sm">

              <Row
                label="Subtotal"
                val={`₹${subtotal.toFixed(0)}`}
              />

              <Row
                label="Platform Fee"
                val={`₹${PLATFORM_FEE}`}
              />

              <Row
                label="Delivery Charge"
                val={`₹${DELIVERY}`}
              />

              <Row
                label="Packaging"
                val={`₹${PACKAGING}`}
              />

              {discount > 0 && (
                <Row
                  label={`Coupon (${applied})`}
                  val={`- ₹${discount}`}
                  color="text-[#4D7C0F]"
                />
              )}

              <div className="border-t border-[#E6DFD5] pt-2 mt-2 flex justify-between font-bold text-lg">

                <span>Grand Total</span>

                <span data-testid="grand-total">
                  ₹{total.toFixed(0)}
                </span>

              </div>

            </div>

            <div className="flex items-center gap-2 mt-4 text-xs text-[#5C4A3D]">
              <Clock className="w-3.5 h-3.5" />
              Estimated delivery within 25 minutes
            </div>

            {!inHours && (
              <div className="mt-2 text-xs text-[#BE123C]">
                Ordering hours: 11:00 AM – 11:00 PM
              </div>
            )}

          </div>
          {/* PAYMENT METHOD */}

          <div className="bg-white border border-[#E6DFD5] rounded-2xl p-5">

            <h3 className="font-display text-lg font-bold mb-3">
              Payment Method
            </h3>

            {/* COD */}

            <label className="flex items-center gap-3 p-3 rounded-xl border border-[#E6DFD5] cursor-pointer mb-3">

              <input
                type="radio"
                checked={payment === "COD"}
                onChange={() => setPayment("COD")}
                data-testid="pay-cod"
              />

              <div>
                <div className="font-semibold text-sm">
                  Cash on Delivery
                </div>

                <div className="text-xs text-[#5C4A3D]">
                  Pay when your order arrives
                </div>
              </div>

            </label>

            {/* ONLINE PAYMENT */}

            <label className="flex items-center gap-3 p-3 rounded-xl border border-[#E6DFD5] cursor-pointer">

              <input
                type="radio"
                checked={payment === "ONLINE"}
                onChange={() => setPayment("ONLINE")}
              />

              <div>
                <div className="font-semibold text-sm">
                  Online Payment (UPI)
                </div>

                <div className="text-xs text-[#5C4A3D]">
                  Google Pay • PhonePe • Paytm • BHIM
                </div>
              </div>

            </label>

            {/* QR */}

            {payment === "ONLINE" && (

              <div className="mt-5 border border-[#E6DFD5] rounded-2xl p-5 text-center bg-[#FFFDF8]">

                <h4 className="text-lg font-bold">
                  Scan & Pay
                </h4>

                <p className="text-sm text-[#5C4A3D] mt-1">
                  Scan using any UPI App
                </p>

                <img
                  src={qrUrl}
                  alt="UPI QR"
                  className="mx-auto my-4 rounded-lg shadow"
                  width={220}
                  height={220}
                />

                <div className="text-3xl font-bold text-[#8B4513]">
                  ₹{total.toFixed(2)}
                </div>

                <div className="mt-3 text-xs text-gray-500 break-all">
                  Merchant : {MERCHANT_NAME}
                </div>

                <div className="text-xs text-gray-500 break-all">
                  UPI : {UPI_ID}
                </div>

                <div className="mt-4 text-xs bg-yellow-50 border border-yellow-300 rounded-lg p-3 text-yellow-800">
                  After completing payment, click <b>Place Order</b>.
                  <br />
                  (Payment verification will be added later.)
                </div>

              </div>

            )}

          </div>

          <Button
            onClick={place}
            disabled={placing}
            className="btn-primary rounded-full w-full h-12 text-base"
            data-testid="place-order-btn"
          >
            {placing
              ? "Placing..."
              : `Place Order · ₹${total.toFixed(0)}`}
          </Button>

        </div>

      </div>

    </div>

  );
}

const Row = ({ label, val, color = "" }) => (
  <div className={`flex justify-between ${color}`}>
    <span>{label}</span>
    <span>{val}</span>
  </div>
);
